import React, { useState } from "react";
import api from "@landinghub/api";
import Background from "../components/Background";
import { CheckCircle2, MapPin, Mail, Phone } from "lucide-react";
import heroImg from "../assets/contact-hero.png";
import "../styles/Contact.css";

const Contact = () => {
  const [form, setForm] = useState({ name: "", email: "", phone: "", notes: "" });
  const [submitted, setSubmitted] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.name || !form.email) {
      alert("Tên và Email là bắt buộc!");
      return;
    }
    try {
      await api.post("/api/leads", { ...form, status: "new" });
      setSubmitted(true);
      setForm({ name: "", email: "", phone: "", notes: "" });
      setTimeout(() => setSubmitted(false), 4000);
    } catch (err) {
      console.error(err);
      alert("Gửi thông tin thất bại. Vui lòng thử lại.");
    }
  };

  return (
    <Background showShapes={false} fullWidth={true}>
      <div className="contact-page">

        {/* Hero */}
        <section className="contact-hero">
          <div className="hero-text">
            <h1>Chúng tôi luôn sẵn sàng hỗ trợ bạn</h1>
            <p>Gửi yêu cầu hoặc câu hỏi, đội ngũ LandingHub sẽ phản hồi nhanh nhất</p>
          </div>
          <div className="hero-image">
            <img src={heroImg} alt="Contact illustration" />
          </div>
        </section>

        {/* Contact Info */}
        <section className="contact-info">
          <div className="info-card">
            <MapPin size={24} /> <span>123 Nguyễn Trãi, Quận 1, TP.HCM</span>
          </div>
          <div className="info-card">
            <Mail size={24} /> <span>support@landinghub.com</span>
          </div>
          <div className="info-card">
            <Phone size={24} /> <span>+84 912 345 678</span>
          </div>
        </section>

        {/* Form */}
        <section className="contact-form-section">
          <div className="contact-card">
            {submitted && (
              <div className="success-message">
                <CheckCircle2 size={24} /> Cảm ơn! Chúng tôi đã nhận thông tin của bạn.
              </div>
            )}
            <form className="contact-form" onSubmit={handleSubmit}>
              <input name="name" value={form.name} onChange={handleChange} placeholder="Họ tên" required />
              <input name="email" type="email" value={form.email} onChange={handleChange} placeholder="Email" required />
              <input name="phone" value={form.phone} onChange={handleChange} placeholder="Số điện thoại" />
              <textarea name="notes" value={form.notes} onChange={handleChange} placeholder="Nội dung" />
              <button type="submit" className="btn-submit">Gửi thông tin</button>
            </form>
          </div>
        </section>

        {/* FAQ */}
        <section className="contact-faq">
          <h2>Câu hỏi thường gặp</h2>
          <div className="faq-item">
            <h3>Làm thế nào để tạo landing page?</h3>
            <p>Bạn chỉ cần chọn template và kéo thả, không cần code.</p>
          </div>
          <div className="faq-item">
            <h3>Form gửi thông tin có bảo mật không?</h3>
            <p>Toàn bộ dữ liệu được lưu trên hệ thống CRM bảo mật của LandingHub.</p>
          </div>
        </section>

        {/* CTA */}
        <section className="contact-cta">
          <h2>Hãy liên hệ ngay để được hỗ trợ nhanh nhất</h2>
        </section>

      </div>
    </Background>
  );
};

export default Contact;
